$$\begin{array}{l}
  {\frac{f\left( {a + h} \right) - f(a)}{h} = \frac{\left( {2a^{2} + 4ah + 2h^{2} - 5a - 5h + 1} \right) - \left( {2a^{2} - 5a + 1} \right)}{h}} \\
  {\phantom{\frac{f\left( {a + h} \right) - f(a)}{h}} = \frac{2a^{2} + 4ah + 2h^{2} - 5a - 5h + 1 - 2a^{2} + 5a - 1}{h}} \\
  {\phantom{\frac{f\left( {a + h} \right) - f(a)}{h}} = {\frac{4ah + 2h^{2} - 5h}{h} = 4a + 2h - 5}}
  \end{array}$$

$$\begin{array}{l}
  {\left( {f \circ g \circ h} \right)(x) = {f\left( {g\left( {h(x)} \right)} \right) = f\left( {g\left( {x + 9} \right)} \right) = f\left( {\cos\left( {x + 9} \right)} \right)}} \\
  {\phantom{\left( {f \circ g \circ h} \right)(x)} = {\left\lbrack \cos(x + 9) \right\rbrack^{2} = F(x)}}
  \end{array}$$

$$\begin{array}{l}
  {{\ln a + \frac{1}{2}\ln b} = {\ln a + \ln b^{1/2}}} \\
  {\phantom{\ln a + \frac{1}{2}\ln b} = {\ln a + \ln\sqrt{b}}} \\
  {\phantom{\ln a + \frac{1}{2}\ln b} = {\ln(a\sqrt{b})}}
  \end{array}$$
